  async function go(m,account){const seq=++sequence;current=m;$('title').textContent=everydayLabels[m]||names[m]||m;$('sidebar').classList.remove('open');$('modeNotice').hidden=m==='dashboard'&&mode==='source';for(const btn of $('nav').querySelectorAll('button')){btn.classList.toggle('active',btn.dataset.view===m);if(btn.dataset.view===m){let parent=btn.parentElement;while(parent&&parent!==$('nav')){if(parent.tagName==='DETAILS')parent.open=true;parent=parent.parentElement;}}}$('content').replaceChildren(el('p','در حال بارگذاری…','muted'));msg('');try{const nodes=m==='dashboard'?await dashboard():await moduleView(m,account);if(mode==='source'&&role==='owner'&&['customers','suppliers'].includes(m))nodes.unshift(manualPartyForm(m));if(mode==='source'&&role==='owner'&&m==='opening_stock_reconciliation')nodes.unshift(stockBulkPanel());if(mode==='source'&&role==='owner'&&m==='bank_evidence')nodes.unshift(bankMovementForm(account));if(mode==='source'&&role==='owner'&&m==='bank_statements')nodes.unshift(bankStatementImportPanel());if(mode==='source'&&role==='owner'&&m==='financial_readiness')nodes.unshift(await openingApprovalPanel(),await currencyAuditPanel());if(mode==='source'&&role==='owner'&&m==='stock_adjustments')nodes.unshift(stockAdjustmentForm());if(seq===sequence)$('content').replaceChildren(...nodes);}catch(e){if(seq===sequence)$('content').replaceChildren(el('div',e.message,'panel error'));}}
  async function enter(user){csrf=user.csrf;role=user.role;mode=user.mode||'demo';opts=await api('/options');$('userName').textContent=user.username+' · '+(role==='owner'?'مالک':'بازبین');renderNavigation();$('login').hidden=true;$('app').hidden=false;$('today').textContent=jalali(new Date().toISOString());await go('dashboard');}
  $('loginForm').addEventListener('submit',async e=>{e.preventDefault();$('loginError').textContent='';const b=e.target.querySelector('button');b.disabled=true;try{const d=new FormData(e.target);await enter(await api('/login','POST',{username:d.get('username'),password:d.get('password'),otp:d.get('otp')}));e.target.reset();}catch(e){$('loginError').textContent=e.message;}finally{b.disabled=false;}});$('logout').addEventListener('click',async()=>{try{await api('/logout','POST',{});}finally{leave();}});$('menu').addEventListener('click',()=>$('sidebar').classList.toggle('open'));$('closeDrawer').addEventListener('click',closeDrawer);$('overlay').addEventListener('click',closeDrawer);document.addEventListener('keydown',e=>{if(e.key==='Escape')closeDrawer();});api('/me').then(enter).catch(()=>{});
